use std::io::{BufRead, Cursor};
fn readings<R: BufRead>(reader: R) -> Result<Vec<u32>, String> {
    reader.lines().enumerate().map(|(index, line)| {
        let line = line.map_err(|error| format!("line {}: {error}", index + 1))?;
        line.trim().parse::<u32>()
            .map_err(|error| format!("line {}: {error}", index + 1))
    }).collect()
}
fn main() {
    assert_eq!(readings(Cursor::new(b"12
7
")), Ok(vec![12, 7]));
    let error = readings(Cursor::new(b"12
bad
")).unwrap_err();
    assert!(error.starts_with("line 2:"));
    println!("Reader checks passed");
}

use std::io::{self, BufRead, Cursor};
fn main() -> io::Result<()> {
    let mut reader = Cursor::new(b"first

third
");
    let mut buffer = String::new();
    let mut records = Vec::new();
    loop {
        buffer.clear();
        let bytes_read = reader.read_line(&mut buffer)?;
        if bytes_read == 0 { break; }
        records.push(buffer.clone());
    }
    assert_eq!(records, vec!["first
", "
", "third
"]);
    println!("Read {} lines, including a blank line", records.len());
    Ok(())
}

trait Measure { fn value(&self) -> i32; }
struct Counter { count: i32 }
struct Offset { base: i32, adjustment: i32 }
impl Measure for Counter { fn value(&self) -> i32 { self.count } }
impl Measure for Offset {
    fn value(&self) -> i32 { self.base + self.adjustment }
}
fn doubled<T: Measure>(source: &T) -> i32 { source.value() * 2 }
fn main() {
    let counter = Counter { count: 7 };
    let offset = Offset { base: 10, adjustment: -2 };
    assert_eq!(doubled(&counter), 14);
    assert_eq!(doubled(&offset), 16);
    println!("Generic checks passed");
}

trait Measure { fn value(&self) -> i32; }
struct Counter(i32);
struct Fixed(i32);
impl Measure for Counter { fn value(&self) -> i32 { self.0 } }
impl Measure for Fixed { fn value(&self) -> i32 { self.0 } }
fn main() {
    let counter = Counter(7);
    let fixed = Fixed(9);
    let sources: [&dyn Measure; 2] = [&counter, &fixed];
    let total: i32 = sources.iter().map(|source| source.value()).sum();
    assert_eq!(total, 16);
    println!("Borrowed total: {total}");
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum State { Draft, Ready, Sent }
#[derive(Clone, Copy)]
enum Action { Validate, Edit, Send }
fn apply(state: &mut State, action: Action) -> Result<(), &'static str> {
    let next = match (*state, action) {
        (State::Draft, Action::Validate) => State::Ready,
        (State::Ready, Action::Edit) => State::Draft,
        (State::Ready, Action::Send) => State::Sent,
        _ => return Err("action is not allowed in this state"),
    };
    *state = next;
    Ok(())
}
fn main() {
    let mut state = State::Draft;
    assert!(apply(&mut state, Action::Send).is_err());
    assert_eq!(state, State::Draft);
    apply(&mut state, Action::Validate).unwrap();
    apply(&mut state, Action::Edit).unwrap();
    assert_eq!(state, State::Draft);
    apply(&mut state, Action::Validate).unwrap();
    apply(&mut state, Action::Send).unwrap();
    assert_eq!(state, State::Sent);
    assert!(apply(&mut state, Action::Validate).is_err());
    assert_eq!(state, State::Sent);
    println!("Workflow checks passed: {state:?}");
}

