fn total(unit: u32, quantity: u32, fee: u32) -> Result<u32, &'static str> {
    let subtotal = unit.checked_mul(quantity).ok_or("subtotal overflow")?;
    subtotal.checked_add(fee).ok_or("fee overflow")
}
fn main() {
    assert_eq!(total(12, 3, 2), Ok(38));
    assert_eq!(total(u32::MAX, 2, 0), Err("subtotal overflow"));
    assert_eq!(total(u32::MAX, 1, 1), Err("fee overflow"));
    println!("Checked total: {}", total(12, 3, 2).unwrap());
}

use std::collections::HashMap;
fn main() {
    let text = "rust crab rust";
    let mut counts: HashMap<&str, usize> = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word).or_insert(0) += 1;
    }
    assert_eq!(counts.get("rust"), Some(&2));
    assert_eq!(counts.get("crab"), Some(&1));
    assert_eq!(counts.get("missing"), None);
    assert_eq!(counts.len(), 2);
    println!("Two distinct keys, three tokens");
}

use std::collections::HashMap;
fn main() {
    let counts = HashMap::from([("rust", 2_usize), ("crab", 1)]);
    let mut rows: Vec<_> = counts.iter().map(|(key, count)| (*key, *count)).collect();
    rows.sort_unstable_by_key(|(key, _)| *key);
    assert_eq!(rows, vec![("crab", 1), ("rust", 2)]);
    for (key, count) in rows { println!("{key}: {count}"); }
}

