fn classify(reading: Option<i32>) -> &'static str {
    match reading {
        Some(0) => "Zero",
        Some(value) if value > 0 => "Positive",
        Some(_) => "Other integer",
        None => "Missing",
    }
}
fn main() {
    assert_eq!(classify(Some(0)), "Zero");
    assert_eq!(classify(Some(5)), "Positive");
    assert_eq!(classify(Some(-2)), "Other integer");
    assert_eq!(classify(None), "Missing");
    println!("Four classification checks passed");
}

fn pair(input: &str) -> Result<(&str, &str), &'static str> {
    let Some((key, value)) = input.split_once(':') else {
        return Err("expected key:value");
    };
    if key.is_empty() { return Err("empty key"); }
    Ok((key, value))
}
fn main() {
    assert_eq!(pair("city:Kyiv"), Ok(("city", "Kyiv")));
    assert_eq!(pair("missing"), Err("expected key:value"));
    assert_eq!(pair(":value"), Err("empty key"));
    println!("Pair checks passed");
}

#[derive(Debug, PartialEq)]
enum LimitError { NotANumber, OutOfRange }
fn parse_limit(input: &str) -> Result<u16, LimitError> {
    let value = input.trim().parse::<u16>()
        .map_err(|_| LimitError::NotANumber)?;
    if !(1..=60).contains(&value) { return Err(LimitError::OutOfRange); }
    Ok(value)
}
fn main() {
    assert_eq!(parse_limit(" 12 "), Ok(12));
    assert_eq!(parse_limit("1"), Ok(1));
    assert_eq!(parse_limit("60"), Ok(60));
    assert_eq!(parse_limit("0"), Err(LimitError::OutOfRange));
    assert_eq!(parse_limit("61"), Err(LimitError::OutOfRange));
    assert_eq!(parse_limit(""), Err(LimitError::NotANumber));
    assert_eq!(parse_limit("many"), Err(LimitError::NotANumber));
    println!("Seven limit checks passed");
}

/// Accept a reading limit from 1 through 60, inclusive.
///
/// ```
/// use limit_rules::accepts;
/// assert!(accepts(60));
/// ```
pub fn accepts(value: u16) -> bool { (1..=60).contains(&value) }

