fn field(line: &str) -> Result<(&str, &str), &'static str> {
    let (key, value) = line.split_once('=').ok_or("missing = separator")?;
    let key = key.trim();
    if key.is_empty() { return Err("empty key"); }
    Ok((key, value.trim()))
}
fn main() {
    assert_eq!(field(" city = Київ "), Ok(("city", "Київ")));
    assert_eq!(field("token=a=b"), Ok(("token", "a=b")));
    assert_eq!(field("missing"), Err("missing = separator"));
    assert_eq!(field(" =value"), Err("empty key"));
    println!("All field checks passed");
}

